function updatePropSim() {
    const a = parseFloat(document.getElementById('input-val-a').value);
    const b = parseFloat(document.getElementById('input-val-b').value);
    const c = parseFloat(document.getElementById('input-val-c').value);

    document.getElementById('badge-val-a').innerText = a;
    document.getElementById('badge-val-b').innerText = b;
    document.getElementById('badge-val-c').innerText = c;

    const add1 = (a + b) + c;
    const add2 = a + (b + c);
    const mult1 = (a * b) * c;
    const mult2 = (c * a) * b;

    document.getElementById('add-val-1').innerText = add1;
    document.getElementById('add-val-2').innerText = add2;
    document.getElementById('add-sub-1').innerText = `(${a} + ${b}) + ${c} = ${add1}`;
    document.getElementById('add-sub-2').innerText = `${a} + (${b} + ${c}) = ${add2}`;

    document.getElementById('mult-res-1').innerText = mult1;
    document.getElementById('mult-res-2').innerText = mult2;
}

function setPropValues(a, b, c) {
    document.getElementById('input-val-a').value = a;
    document.getElementById('input-val-b').value = b;
    document.getElementById('input-val-c').value = c;
    updatePropSim();
}

document.addEventListener('DOMContentLoaded', () => {
    updatePropSim();
});
